11	  workspace.add({ id: 'architecture', title: '架构备忘', body: '本地优先的文档与双向链接基线。返回 [[welcome]]。', tags: ['架构', 'markdown'] });
12	  const result = {
13	    product: 'Lattice Workbench',
14	    documents: workspace.list(),
15	    search: workspace.search('markdown').map(({ id, title }) => ({ id, title })),
16	    relationships: Object.fromEntries(workspace.list().map(({ id }) => [id, workspace.links(id)])),
17	  };
