33	    fs.writeFileSync(temp, content, 'utf8');
34	    fs.renameSync(temp, file);
35	  } catch (error) {
36	    try {
37	      fs.rmSync(temp, { force: true });
38	    } catch {
39	      // best-effort cleanup of the staging file
