I'll create tasks to track progress, then implement the batch endpoint in server.js, and add tests.

Let me set up the task list and start implementing.

Key design decisions:
1. New `POST /batch` route.
2. Validate request body structure → INVALID_BATCH.
3. Validate documents → INVALID_DOCUMENT (single-doc rules).
4. Validate revisions → INVALID_REVISION (single-doc rules).
5. Duplicate target ids → INVALID_BATCH.
6. If-Match required (same as single routes).
7. State checks against pre-commit state (409/404).
8. Title conflict check on final projected state (409).
9. Apply all operations to candidate, record history per changed doc.
10. dryRun → return projected snapshot without saving.
11. No changes → keep current ETag, no file write.
12. Save failure → 500/IO_ERROR, state unchanged.

Let me implement. I'll modify server.js to add the batch handler.

Let me think about the structure of the code. I'll add:
- A `validateBatchRequest` function that parses and validates the batch envelope.
- A `commitBatch` function that applies operations and saves.
- A `batch` route handler.

Let me write the code now.

For the validation, I need to be careful about the order and the exact error codes. Let me define:

```js
const BATCH_ACTIONS = new Set(['create', 'replace', 'delete', 'restore']);
const MAX_BATCH_OPERATIONS = 100;

function validateBatchRequest(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    throw new HttpError(400, 'INVALID_BATCH', 'batch body must be an object');
  }
  const keys = Object.keys(data);
  for (const key of keys) {
    if (key !== 'operations' && key !== 'dryRun') {
      throw new HttpError(400, 'INVALID_BATCH', `unknown batch field: ${key}`);
    }
  }
  if (!Array.isArray(data.operations)) {
    throw new HttpError(400, 'INVALID_BATCH', 'operations must be an array');
  }
  if (data.operations.length < 1 || data.operations.length > MAX_BATCH_OPERATIONS) {
    throw new HttpError(400, 'INVALID_BATCH', `operations must contain 1 to ${MAX_BATCH_OPERATIONS} items`);
  }
  const dryRun = data.dryRun === undefined ? false : data.dryRun;
  if (typeof dryRun !== 'boolean') {
    throw new HttpError(400, 'INVALID_BATCH', 'dryRun must be a boolean');
  }

  const operations = data.operations.map((op, index) => {
    if (!op || typeof op !== 'object' || Array.isArray(op)) {
      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] must be an object`);
    }
    const type = op.type;
    if (typeof type !== 'string' || !BATCH_ACTIONS.has(type)) {
      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has an unknown type`);
    }
    const opKeys = Object.keys(op);
    const expectedKeys = type === 'create' || type === 'replace'
      ? ['type', 'document']
      : type === 'delete'
        ? ['type', 'id']
        : ['type', 'id', 'revision'];
    if (opKeys.length !== expectedKeys.length || !expectedKeys.every((k) => opKeys.includes(k))) {
      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has invalid fields for ${type}`);
    }

    if (type === 'create' || type === 'replace') {
      if (!op.document || typeof op.document !== 'object' || Array.isArray(op.document)) {
        throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] document must be an object`);
      }
      const document = validateDocument(op.document);
      return { type, document };
    }

    if (typeof op.id !== 'string') {
      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] id must be a string`);
    }

    if (type === 'delete') {
      return { type, id: op.id };
    }

    // restore
    if (op.revision === undefined) {
      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] restore requires a revision`);
    }
    if (!Number.isInteger(op.revision) || op.revision < 1) {
      throw new HttpError(400, 'INVALID_REVISION', `operations[${index}] revision must be a positive integer`);
    }
    return { type, id: op.id, revision: op.revision };
  });

  // Duplicate target ids.
  const seen = new Set();
  for (const op of operations) {
    const id = op.type === 'create' || op.type === 'replace' ? op.document.id : op.id;
    if (seen.has(id)) {
      throw new HttpError(400, 'INVALID_BATCH', `duplicate target id in batch: ${id}`);
    }
    seen.add(id);
  }

  return { operations, dryRun };
}
```

Wait, I need to think about the revision validation. The spec says "版本错误沿用单篇规则" (version errors follow single-doc rules). In single restore, the revision validation is:
```js
if (!data || typeof data !== 'object' || Array.isArray(data)
  || Object.keys(data).length !== 1 || !Object.hasOwn(data, 'revision')
  || !Number.isInteger(data.revision) || data.revision < 1) {
  throw new HttpError(400, 'INVALID_REVISION', ...);
}
```

So `revision` must be a positive integer. If it's a string, boolean, null, etc. → INVALID_REVISION. But in my structural validation, I check `op.revision === undefined` → INVALID_BATCH. Then `!Number.isInteger(op.revision) || op.revision < 1` → INVALID_REVISION.

But wait, what if `revision` is a string "1"? Then `op.revision === undefined` is false, so we proceed to `!Number.isInteger("1")` → true → INVALID_REVISION. Good, that matches single restore behavior.

What if `revision` is `true`? `Number.isInteger(true)` → false → INVALID_REVISION. Good.

What if `revision` is `null`? `Number.isInteger(null)` → false → INVALID_REVISION. Good.

What if `revision` is `1.5`? `Number.isInteger(1.5)` → false → INVALID_REVISION. Good.

What if `revision` is `0`? `0 < 1` → true → INVALID_REVISION. Good.

What if `revision` is `-1`? `-1 < 1` → true → INVALID_REVISION. Good.

